using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.AI;using Unity.AI.Navigation;using UnityEditor;using UnityEditor.SceneManagement;using PaperPixelGames.Core.DressingSceneSystem;using SushiAndFish.Casino;using SushiAndFish.CityExpansion;using Object=UnityEngine.Object;
public static class CasinoDetailedNavigation {
 [Serializable]public class Result{public string utc,error,asset;public bool saved,parkBenchReachable;public int restaurantSeats;}
 public static void Rebuild(){var q=new Result{utc=DateTime.UtcNow.ToString("o")};try{
  var gs=EditorSceneManager.OpenScene("Assets/SushiAndFish/Modules/OriginalIsland/Scenes/GameState.unity");var ds=EditorSceneManager.OpenScene("Assets/SushiAndFish/Modules/OriginalIsland/Scenes/DressingScenes/100_Dressing_City_01.unity",OpenSceneMode.Additive);var all=gs.GetRootGameObjects().Concat(ds.GetRootGameObjects()).SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var active=all.ToDictionary(t=>t.gameObject,t=>t.gameObject.activeSelf);foreach(var d in all.Select(t=>t.GetComponent<DressingSceneRoot>()).Where(d=>d))d.ActivateAllImmediate();var casino=Object.FindFirstObjectByType<ParkCasinoIntegration>();var colliders=casino.permanentExterior.GetComponentsInChildren<Collider>(true);var enabled=colliders.Select(c=>c.enabled).ToArray();for(int i=0;i<colliders.Length;i++)if(!colliders[i].isTrigger)colliders[i].enabled=true;CasinoHostRepair.TrimExterior(casino.permanentExterior);Physics.SyncTransforms();
  var surface=all.Select(t=>t.GetComponent<NavMeshSurface>()).First(s=>s);surface.useGeometry=NavMeshCollectGeometry.PhysicsColliders;surface.BuildNavMesh();q.asset=AssetDatabase.GenerateUniqueAssetPath("Assets/SushiAndFish/Casino/DetailedRevision20261021/TownFinalNavigation.asset");AssetDatabase.CreateAsset(surface.navMeshData,q.asset);var filter=new NavMeshQueryFilter{agentTypeID=surface.agentTypeID,areaMask=NavMesh.AllAreas};
  foreach(var seat in all.Select(t=>t.GetComponent<CityDiningSeat>()).Where(s=>s)){var path=new NavMeshPath();if(NavMesh.CalculatePath(new Vector3(66,3.1f,-13),seat.approach.position,filter,path)&&path.status==NavMeshPathStatus.PathComplete)q.restaurantSeats++;}
  if(NavMesh.SamplePosition(new Vector3(-144.7f,3.03f,-19.2f),out var h,2,filter)){var path=new NavMeshPath();q.parkBenchReachable=NavMesh.CalculatePath(new Vector3(-50,3.1f,-2),h.position,filter,path)&&path.status==NavMeshPathStatus.PathComplete;}
  for(int i=0;i<colliders.Length;i++)colliders[i].enabled=enabled[i];foreach(var a in active)if(a.Key&&a.Key.activeSelf!=a.Value)a.Key.SetActive(a.Value);
  if(q.restaurantSeats!=12||!q.parkBenchReachable)throw new Exception("Navigation not complete: seats="+q.restaurantSeats+" park="+q.parkBenchReachable);EditorUtility.SetDirty(surface);EditorSceneManager.MarkSceneDirty(gs);EditorSceneManager.SaveScene(gs);AssetDatabase.SaveAssets();q.saved=true;IslandFrontEndBuilder.RefreshMenuPresentation();EditorSceneManager.OpenScene("Assets/Scenes/Main.unity");
 }catch(Exception e){q.error=e.ToString();Debug.LogException(e);throw;}finally{File.WriteAllText(Path.Combine(IslandRevision20261018.Reports,"casino-detailed-navigation.json"),JsonUtility.ToJson(q,true));}}
 public static void RebuildAndCoast(){CasinoControlBindingAudit.Verify();Rebuild();CasinoDetailedFinalVerification.Verify();UnityEditor.SessionState.SetBool("SushiAndFish.CityExpansionAudit.coastAndDice",true);UnityEditor.SessionState.SetBool("SushiAndFish.CityExpansionAudit.crapsOnly",true);CityExpansionPlayAudit.RoofsAndCoast();}
 public static void ApplyFinalRoads(){CasinoDetailedRepair.ApplyRoadsOnly();Rebuild();CasinoControlBindingAudit.Verify();CasinoDetailedFinalVerification.Verify();}
 public static void FinalVerifiedPlay(){CasinoControlBindingAudit.Verify();CasinoDetailedFinalVerification.Verify();FinalPlay();}
 public static void FinalPlay(){UnityEditor.SessionState.SetBool("SushiAndFish.CityExpansionAudit.coastAndDice",false);UnityEditor.SessionState.SetBool("SushiAndFish.CityExpansionAudit.crapsOnly",false);UnityEditor.SessionState.SetBool("SushiAndFish.CityExpansionAudit.environment",true);UnityEditor.SessionState.SetBool("SushiAndFish.CityExpansionAudit.environmentCompare",false);CityExpansionPlayAudit.RoofsAndCoast();}
 public static void VerifyAndRun(){CasinoControlBindingAudit.Verify();CasinoDetailedFinalVerification.Verify();UnityEditor.SessionState.SetBool("SushiAndFish.CityExpansionAudit.coastAndDice",true);UnityEditor.SessionState.SetBool("SushiAndFish.CityExpansionAudit.crapsOnly",true);CityExpansionPlayAudit.RoofsAndCoast();}
}
